function LuckRewardsDialog:RuleClick()
    ---@type LuckScheduleIdVo
    local luckScheduleIdVo = CfUtils.GetCfVo(AutoIds.IdSetting4081,"LuckScheduleIdVo" , self.currentScheduleId)
    if checkInt(luckScheduleIdVo.ruleId) > 0 then
        CfUtils.ShowModuleToast(luckScheduleIdVo.ruleId)
    end
end
function LuckRewardsDialog:DrawClick(index)
    if self.callTimes <= 0 then
        GameUtils.Toast(localize("暂无抽奖次数"))
        return
    end
    local callFunc = function ()
        if self.drawRewardIds[tostring(index)] then
            return
        end
        GameUtils.Request(Interfaces.OverseaLuckyRewardCall ,{position = index}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local data = response.data
                local callRewardsId = data.callRewardsId
                GoodsUtils.DrawRewards(data.rewards,true)
                self.drawRewardIds = self.drawRewardIds or {}
                self.drawRewardIds[tostring(callRewardsId)] = index
                self.callTimes = self.callTimes - 1
                self.currentScheduleIdData ,self.sortTable= self:GetCurrentSecheduleIdData()
                ---@type LuckRewardVo
                local luckRewardVo = CfUtils.GetCfVo(AutoIds.IdSetting4080,"LuckRewardVo" ,callRewardsId)
                if luckRewardVo.type <= 3 then
                    local BtnRewrad = self["BtnRewrad".. luckRewardVo.type]
                    local UIFX_Goods_Spiral = BtnRewrad:Find("Root/UIFX_Goods_Spiral")
                    CfUtils.PlayAnimation(UIFX_Goods_Spiral , "ResidentLuckyRewardDialog2990_BtnRewrad_Received")
                    self:UpdateDrawRewardByType(luckRewardVo.type)
                end
                CfUtils.StartCoroutineWithBlocker(function()
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                    UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = data.rewards, 
                            cb = function()
                                if self:IsAllDraw() then
                                    self:Refresh()
                                end
                            end}
                        }
                    )          
                end)
                self:UpdateTimes() 
                self:CheckRedPoint()
                self.sortTable[index] = data.callRewardsId
                local item = self.ScrollView:GetShownItemByItemIndex(index -1 )
                if isNotNull(item) then
                    local nodeEnv = CfUtils.GetLuaScr(item, LuckRewardsCellStr)
                    nodeEnv:ResidentLuckyRewardDialog2990_Flip()
                    nodeEnv:UpdateUI(index , self.sortTable[index] , self , false)    
                end
            end
        end)
    end

    if (checkInt(self.newScheduleId) ~= checkInt(self.currentScheduleId) and ( checkInt(self.newScheduleId) > 0)) then
        GameUtils.SecondConfirm(localize('有新一期的奖池，是否立即替换当前奖池？'), function()
            self:RefreshClick()
        end , function()
            callFunc()
        end)
    else             
        callFunc()
    end
end

function LuckRewardsDialog:IsAllDraw()
    local isAllDraw = true
    for k, v in pairs(self.currentScheduleIdData) do
        for kk, vv in pairs(v) do
            if not  vv.isRewards then
                isAllDraw = false
                break
            end
        end
    end
    return isAllDraw   
end

function LuckRewardsDialog:UpdateBigDrawRewards()
    for i =1 , 3 do
        self:UpdateDrawRewardByType(i)
    end
end

function LuckRewardsDialog:UpdateDrawRewardByType(type)
    local BtnRewrad = self["BtnRewrad" .. type]
    local data =  self.currentScheduleIdData[tostring(type)] 
    local vv = data[1]
    local goodsId = vv.vo.rewards.goodsId
    local goodsImagePath = GoodsConfMgr:GetInstance():GetPhotoPathById(vv.vo.rewards.goodsId) 
    local goodsVo  = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    local transform = BtnRewrad.transform:Find("Root").transform
    local imageGoodsImage = transform:Find("ImgGoodsIcon")      
    CfUtils.FillImage(imageGoodsImage , goodsImagePath)
    local num = vv.vo.rewards.goodsNum
    local TextReview = transform:Find("TextReview")
    CfUtils.FillText(TextReview , "x" .. num)
    local ImgGet = transform:Find("ImgGet")
    local imageStar =  transform:Find("ImgBgStar/GoodStar/ImgStar")
    local UIFX_Goods_Spiral =  transform:Find("UIFX_Goods_Spiral")
    if isNotNull(imageStar) then
        local imageStarParent = imageStar.transform.parent
        for i =1 , checkInt(goodsVo.quality) do
            local object = imageStarParent.transform:Find("ImgStar" .. i )
            if isNull(object) then
                object = GameObject.Instantiate(imageStar, imageStarParent)
                object.name = "ImgStar" .. i 
                KTool.SetActive(object , true)
            end
        end
    end

    SetButtonAction(BtnRewrad , function ()
        GameUtils.ShowCommonTipsBoard(BtnRewrad, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id, true)
    end)
    KTool.SetActive(ImgGet , vv.isRewards)
    CfUtils.GetOrAddComponent(imageGoodsImage, UIGrayGraphics):MarkGray(vv.isRewards)    
    KTool.SetActive(UIFX_Goods_Spiral , not vv.isRewards)    
    if (not KTool.IsActive(BtnRewrad)) then
        KTool.SetActive(BtnRewrad , true)
    end
end
function LuckRewardsDialog:RefreshClick()
    GameUtils.Request(Interfaces.OverseaLuckyRewardRefresh ,{}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            GameUtils.Toast(localize("奖池已刷新"))
            self:Refresh()
            self.currentScheduleId = checkInt(self.newScheduleId)
        end
    end)
end

function LuckRewardsDialog:Refresh()
    GameUtils.Request(Interfaces.OverseaLuckyRewardHome ,{}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local data = response.data
            self.callTimes = checkInt(data.callTimes) 
            self.dailyGetCallTimes =  checkInt(data.dailyGetCallTimes) 
            self.drawRewardIds =  data.drawRewardIds
            self.currentScheduleId =  data.currentScheduleId
            self.newScheduleId =  data.newScheduleId
            if checkInt(self.currentScheduleId) == 0 and checkInt(self.newScheduleId) > 0 then
                self.currentScheduleId = checkInt(self.newScheduleId)
            end
            self.currentScheduleIdData , self.sortTable  = self:GetCurrentSecheduleIdData()
            self:UpdateBigDrawRewards()
            self:RefreshScrollView()
            self:UpdateTimes()
            self:CheckRedPoint()
        end
    end)
    xRecord.record('4-015')
end
function LuckRewardsDialog:RefreshScrollView()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(#self.sortTable, Bind(self, self.OnGetItemByIndex))
    else 
        GameUtils.ReloadData(self.ScrollView, #self.sortTable)    
    end  
end

function LuckRewardsDialog:UpdateTimes()
    CfUtils.FillText(self.TextNumberOfLuckyDraws , localize("剩余抽奖次数:_num_", {_num_ = self.callTimes}) )
    CfUtils.FillText(self.TodayTextDesc , self.dailyGetCallTimes)
end

function LuckRewardsDialog:OnGetItemByIndex(listView, listIndex)
    if listIndex < 0 then return end
    local cell = listView:NewListViewItem("Cell")   
    ---@type SelectServerNode
    local nodeEnv = CfUtils.GetLuaScr(cell, LuckRewardsCellStr)
    if nodeEnv then
        local index = listIndex + 1 
        nodeEnv:UpdateUI(index , self.sortTable[index] , self)
        -- CfUtils.PlayAnimation(cell  ,"ResidentLuckyRewardDialog2990_Cell_Idle")
    end
    return cell
end

function LuckRewardsDialog:CheckRedPoint()
    if checkInt(self.callTimes) == 0 then
        GameUtils.SetRedPointNum(Constants.RedPointConst.LuckDraw , 0)
    else
        GameUtils.SetRedPointNum(Constants.RedPointConst.LuckDraw , 1)
    end
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.LuckDraw)
end

function LuckRewardsDialog:GetCurrentSecheduleIdData()
    local curentData = {
        ["1"] = {},
        ["2"] = {},
        ["3"] = {},
        ["4"] = {},
        ["5"] = {}
    }
    ---@type LuckRewardVo[]
    local luckRewardVos = CfUtils.GetWholeVo(AutoIds.IdSetting4080,"LuckRewardVo")
    local sortTable = {}
    for i, luckRewardVo in pairs(luckRewardVos) do
        if luckRewardVo.group == self.currentScheduleId then
            local data = {
                vo =  luckRewardVo,
                isRewards = false
            }
            for rewardsId, position  in pairs(self.drawRewardIds or {}) do
                if checkInt(rewardsId) == luckRewardVo.id then
                    data.isRewards = true
                    sortTable[checkInt(position)] = checkInt(rewardsId) 
                end
            end
            local rewardType = tostring(luckRewardVo.type)
            curentData[rewardType][#curentData[rewardType]+1] = data
        end
    end
    local index = 0 
    for i = 1 , 5 do
        local data = curentData[tostring(i)]
        for k, v in pairs(data) do
            index = index + 1
            if  checkInt(sortTable[index]) == 0 then
                sortTable[index] = 0 
            end 
        end
    end
    return curentData,sortTable 
end

